/**
 * @file    wheel_config.h
 * @brief   Central, user-tunable configuration of the steering wheel firmware.
 *
 * Every macro can be overridden from the command line, e.g.
 *   cmake --preset Debug -DSIMULATE_INPUTS=ON -DSTEERING_SOURCE=POT
 */
#ifndef WHEEL_CONFIG_H
#define WHEEL_CONFIG_H

/* Values measured on the real hardware come from config/hardware_profile.toml
 * through tools/gen_config.py (regenerated by CMake on every build). The
 * #ifndef defaults below are only fallbacks with the same placeholder values. */
#include "wheel_config_generated.h"

/* ------------------------------------------------------------------------- */
/* Force feedback (everything that can write to the ODrive lives in          */
/* Core/Src/ffb and is compiled only with -DWHEEL_FFB=ON).                   */
/* ------------------------------------------------------------------------- */
#ifndef WHEEL_FFB
#define WHEEL_FFB                0
#endif
#ifndef WHEEL_FFB_ARM_ALLOWED
#define WHEEL_FFB_ARM_ALLOWED    0
#endif

/* ------------------------------------------------------------------------- */
/* Input source selection                                                    */
/* ------------------------------------------------------------------------- */
#define STEERING_SOURCE_POT      1   /* potentiometer on PA1 (ADC1_IN2)      */
#define STEERING_SOURCE_ENCODER  2   /* encoder wired to the STM32 TIM3 (old) */
#define STEERING_SOURCE_ODRIVE   3   /* position read from the ODrive (UART)  */

#ifndef STEERING_SOURCE
#define STEERING_SOURCE          STEERING_SOURCE_ODRIVE
#endif

/* 1 = generate a sine wave on X and toggle buttons one by one, touch no
 * external hardware (nothing needs to be wired to verify the HID path). */
#ifndef SIMULATE_INPUTS
#define SIMULATE_INPUTS          0
#endif

/* ------------------------------------------------------------------------- */
/* Steering encoder (LPD3806-600BM)                                          */
/* ------------------------------------------------------------------------- */
/* 600 pulses/rev * 4 (x4 quadrature) = 2400 counts per encoder revolution.
 * Belt ratio between wheel and encoder is assumed 1:1 for now. */
#ifndef ENCODER_COUNTS_PER_WHEEL_REV
#define ENCODER_COUNTS_PER_WHEEL_REV  2400
#endif

/* Total wheel rotation from full left lock to full right lock, in degrees.
 * Used by the ENCODER and ODRIVE sources. TODO(TBD): confirm 540. */
#ifndef WHEEL_LOCK_TO_LOCK_DEG
#define WHEEL_LOCK_TO_LOCK_DEG        540
#endif

/* 1 = swap steering direction. */
#ifndef ENCODER_INVERT_DIRECTION
#define ENCODER_INVERT_DIRECTION      0
#endif

/* Encoder counts that span the whole lock-to-lock range (3600 by default).
 * The centre is the power-up position, so each side gets half of this. */
#define ENCODER_COUNTS_FULL_RANGE \
  ((ENCODER_COUNTS_PER_WHEEL_REV * WHEEL_LOCK_TO_LOCK_DEG) / 360)

/* TIM3 input capture filter (ICxF, 0..15). 8 = fDTS/8, N=6 -> about 1 us at
 * 48 MHz: rejects ringing/glitches, still far above the 600 PPR pulse rate. */
#define ENCODER_INPUT_FILTER          8U

/* ------------------------------------------------------------------------- */
/* MCP23017 button expander (I2C1, PB6 = SCL, PB7 = SDA)                      */
/* ------------------------------------------------------------------------- */
#ifndef MCP23017_I2C_ADDR_7BIT
#define MCP23017_I2C_ADDR_7BIT        0x20U  /* A0..A2 tied to GND            */
#endif
#define BUTTON_DEBOUNCE_MS            5U     /* samples are taken every 1 ms  */
#define BUTTON_COUNT                  10U    /* bits 0..9 of the report       */
#define MCP23017_RETRY_MS             250U   /* retry period when absent      */
#define MCP23017_XFER_TIMEOUT_MS      10U    /* abort a stuck transfer        */

/* I2C1 TIMINGR for 400 kHz with I2C1CLK = SYSCLK = 48 MHz (see README). */
#define I2C1_TIMING_400KHZ_48MHZ      0x10930F20UL

/* 1 = the chip inverts the inputs itself (IPOLA/IPOLB = 0xFF), 0 = invert in
 * software. Both give 1 = pressed in the report. */
#ifndef MCP23017_USE_IPOL
#define MCP23017_USE_IPOL             0
#endif

/* ------------------------------------------------------------------------- */
/* HID report                                                                */
/* ------------------------------------------------------------------------- */
/* Reserved pedal axes: value reported until the pedals exist. 0 = released. */
#ifndef HID_AXIS_Y_NEUTRAL
#define HID_AXIS_Y_NEUTRAL            0U     /* throttle (SS49E Hall, later)  */
#endif
#ifndef HID_AXIS_Z_NEUTRAL
#define HID_AXIS_Z_NEUTRAL            0U     /* brake (load cell + HX711)     */
#endif

/* "Set centre": hold the blue user button B1 (PA0) this long. */
#ifndef SET_CENTRE_HOLD_MS
#define SET_CENTRE_HOLD_MS            1000U
#endif

/* ------------------------------------------------------------------------- */
/* ODrive link (USART1: PA9 = TX -> ODrive GPIO2, PA10 = RX <- ODrive GPIO1)  */
/* READ-ONLY: the firmware only ever sends "f <axis>" and "r <path>".         */
/* ------------------------------------------------------------------------- */
#ifndef ODRIVE_UART_BAUD
#define ODRIVE_UART_BAUD              115200U
#endif

#ifndef ODRIVE_AXIS
#define ODRIVE_AXIS                   0      /* axis0 */
#endif

/* Request period: 10 ms = 100 Hz (5 ms = 200 Hz). */
#ifndef ODRIVE_POLL_PERIOD_MS
#define ODRIVE_POLL_PERIOD_MS         10U
#endif

/* No reply within this time -> count a timeout, allow the next request. */
#ifndef ODRIVE_REPLY_TIMEOUT_MS
#define ODRIVE_REPLY_TIMEOUT_MS       8U
#endif

/* No valid position for this long -> data is flagged stale. */
#ifndef ODRIVE_STALE_MS
#define ODRIVE_STALE_MS               100U
#endif

/* ODrive "turns" per one turn of the wheel. Normally set by the profile
 * (motor.motor_turns_per_wheel_rev; ODrive turns = motor turns once
 * axis0.encoder.config.cpr = counts per MOTOR turn, see gen_config.py).
 * TODO(TBD): measure (tools/measure_counts.py). Fallback 1.0 = direct drive. */
#ifndef ODRIVE_TURNS_PER_WHEEL_REV
#define ODRIVE_TURNS_PER_WHEEL_REV    1.0f
#endif

/* 0 = off (default). > 0: if no valid position arrived for this long and
 * data comes back, the ODrive probably rebooted (no index pulse: its
 * position restarted at 0), so the next sample becomes the new centre. */
#ifndef ODRIVE_RECENTRE_AFTER_STALE_MS
#define ODRIVE_RECENTRE_AFTER_STALE_MS 0U
#endif

/* TODO(TBD): 1 = swap the steering direction of the ODrive source. */
#ifndef ODRIVE_INVERT_DIRECTION
#define ODRIVE_INVERT_DIRECTION       0
#endif

/* ------------------------------------------------------------------------- */
/* Potentiometer fallback (PA1)                                              */
/* ------------------------------------------------------------------------- */
#define POT_DEADBAND_16BIT            64U    /* ~4 ADC counts, as before      */

#endif /* WHEEL_CONFIG_H */
